FileImage asset(String name) => FileImage(File('test/assets/$name'));

List<List<num>> flatten(List<CgColor> colors) => [
      for (final c in colors) [c.r, c.g, c.b, c.percentage]
    ];

// Expected results, generated by v2.0.0.
