/// Bucket id computed the way v2.0.0 did.
int referenceBucket(int r, int g, int b) {
  final hslValues = hsl(r, g, b);
  final luminance = (r * 0.2126 + g * 0.7152 + b * 0.0722).toInt();
  return ((luminance & 192) >> 2) |
      ((hslValues[0] & 192) >> 4) |
      ((hslValues[2] & 192) >> 6);
}

void main() {
  final binding = WidgetsFlutterBinding.ensureInitialized();

  group('extractColor', () {
    goldens.forEach((name, expected) {
      test('matches v2.0.0 for $name', () async {
        expect(flatten(await extractColor(asset(name), 10)), expected);
      });
    });

    test('returns fewer colors when fewer are present', () async {
      expect(await extractColor(asset('512x512.png'), 64), hasLength(4));
    });

    test('completes with an error when the image fails to load', () async {
      await expectLater(
          extractColor(asset('does_not_exist.png'), 10), throwsA(anything));
      await expectLater(
          extractColor(MemoryImage(Uint8List.fromList([1, 2, 3, 4])), 10),
          throwsA(anything));
    });
  });

  test('extractColorFromImage matches extractColor', () async {
    final image = await getImageFromProvider(asset('264x264.png'));
    addTearDown(image.dispose);
    expect(flatten(await extractColorFromImage(image, 10)),
        goldens['264x264.png']);
    // The image is left for the caller to dispose.
    expect(image.debugDisposed, isFalse);
  });

  group('extractColorFromRgba', () {
    test('averages and ranks colors', () {
      final rgba = Uint8List.fromList([
        250, 0, 0, 255, //
        240, 10, 0, 255,
        230, 20, 0, 255,
        0, 0, 200, 255,
      ]);
      final colors = extractColorFromRgba(rgba, 10);
      expect(flatten(colors), [
        [240, 10, 0, 0.75],
        [0, 0, 200, 0.25],
      ]);
      expect(colors.first.toColor(), const Color(0xFFF00A00));
      expect(colors.first.toString(), 'CgColor(240, 10, 0, 0.75)');
    });

    test('fast path matches the original code path', () async {
      // Lists that aren't a Uint8List go through the original code.
      final image = await getImageFromProvider(asset('264x264.jpg'));
      addTearDown(image.dispose);
      final byteData = await image.toByteData();
      final photo = byteData!.buffer.asUint8List();
      final noise = Uint8List.fromList(
          List.generate(64 * 64 * 4, (i) => (i * 2654435761) >> 7 & 0xFF));
      for (final rgba in [photo, noise]) {
        expect(sampleFromList(rgba), sampleFromList(List<int>.of(rgba)));
      }
    });

    test('does not overflow on very large images', () {
      // Enough white pixels for a channel sum to overflow 32 bits.
      const pixels = 17000000;
      final rgba = Uint8List(pixels * 4)..fillRange(0, pixels * 4, 255);
      final colors = extractColorFromRgba(rgba, 10);
      expect(flatten(colors), [
        [255, 255, 255, 1.0]
      ]);
      final samples = sampleFromList(rgba);
      final white = colorBucket(255, 255, 255) << 8;
      expect(samples.sublist(white, white + 4),
          [255 * pixels, 255 * pixels, 255 * pixels, pixels]);
    });
  });

  test('colorBucket matches v2.0.0 for every 8 bit RGB color', () {
    var mismatches = 0;
    for (var r = 0; r < 256; r++) {
      for (var g = 0; g < 256; g++) {
        for (var b = 0; b < 256; b++) {
          if (colorBucket(r, g, b) != referenceBucket(r, g, b)) mismatches++;
        }
      }
    }
    expect(mismatches, 0);
  });

  group('getImageFromProvider', () {
    test('resolves an image', () async {
      final image = await getImageFromProvider(asset('264x264.jpg'));
      addTearDown(image.dispose);
      expect([image.width, image.height], [264, 264]);
    });

    test('stops listening once the image is resolved', () async {
      final provider = asset('264x264.png');
      await extractColor(provider, 10);
      final stream = provider.resolve(ImageConfiguration.empty);
      // ignore: invalid_use_of_protected_member
      expect(stream.completer!.hasListeners, isFalse);
    });

    test('uses the first frame of animated images', () async {
      final errors = <Object>[];
      final onError = FlutterError.onError;
      FlutterError.onError = (details) => errors.add(details.exception);
      addTearDown(() => FlutterError.onError = onError);

      // Nothing drives frames in tests, so fake them to let it animate.
      var elapsed = Duration.zero;
      final frames = Timer.periodic(const Duration(milliseconds: 5), (_) {
        elapsed += const Duration(milliseconds: 5);
        binding.handleBeginFrame(elapsed);
        binding.handleDrawFrame();
      });
      addTearDown(frames.cancel);

      // Frames are red, blue, then green.
      final colors = await extractColor(asset('animated.gif'), 10);
      expect(flatten(colors), [
        [255, 0, 0, 1.0]
      ]);
      await Future<void>.delayed(const Duration(milliseconds: 200));
      expect(errors, isEmpty);
    });
  });

  test('sampleFromList keeps its layout', () {
    // The packed index of a color is its bucket id << 8.
    final samples = sampleFromList(Uint8List.fromList([10, 20, 30, 255]));
    final index = referenceBucket(10, 20, 30) << 8;
    expect(samples, hasLength(16384));
    expect(samples.sublist(index, index + 4), [10, 20, 30, 1]);
    expect(samples.where((v) => v != 0), hasLength(4));
  });
}
